  function bindEvidence(){document.querySelectorAll('[data-ev-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.evAction,id=el.dataset.evId;if(a==='demo')return demoEvidence();if(a==='view')evidenceView=id;if(a==='hypothesis')selected=id;if(a==='select')activeEvidence=id;if(a==='knowledge')return context.navigate('resource-knowledge');if(a==='questions')return context.navigate('space-questions');if(a==='new')return evidenceForm();if(a==='edit')return evidenceForm(evdb().evidence.find(e=>e.id===id));if(a==='review')return reviewEvidence(id);if(a==='plan')return planEvidence();if(a==='task')return context.openTask(id);if(a==='export')return exportEvidence();if(a==='check'){evdb().checkRun=stamp();save();}context.render();});const q=document.getElementById('ev-search');if(q)q.onchange=()=>{query=q.value;context.render();};const f=document.getElementById('ev-filter');if(f)f.onchange=()=>{evidenceFilter=f.value;context.render();};}

  
