  function fileTreeRows(rows){const root={children:new Map(),files:[],path:''};for(const r of rows){const parts=(r.path||('/资料/'+r.label)).split('/').filter(Boolean);parts.pop();let n=root;for(const part of parts){if(!n.children.has(part))n.children.set(part,{children:new Map(),files:[],path:n.path+'/'+part,name:part});n=n.children.get(part);}n.files.push(r);}const walk=(n,depth)=>[...n.children.values()].map(dir=>`<tr class="sa-directory-row"><td></td><td colspan="6"><button class="sa-tree-directory" style="padding-left:${depth*16}px" data-sa-toggle="${escape(dir.path)}">${collapsedFolders.has(dir.path)?'›':'⌄'} <span class="sa-folder-icon">▰</span> ${escape(dir.name)}</button></td></tr>${collapsedFolders.has(dir.path)?'':walk(dir,depth+1)}`).join('')+n.files.map(r=>`<tr><td>${r.draft?'':`<input type="checkbox" aria-label="选择 ${escape(r.label)}" data-sa-select="${escape(r.id)}" ${assetSelection.has(r.id)?'checked':''}>`}</td><td><button class="sa-tree-file" style="padding-left:${depth*16}px" data-sa-detail="${escape(r.id)}"><span class="sa-file-icon">▤</span> ${escape(r.label)}</button></td><td>${escape(r.type)}</td><td title="${escape(r.path)}">${escape(r.sourceLabel)}<small>${escape(r.originGroup||'')}</small></td><td>${escape(r.creator)}${r.creator===ME?' <em class="sa-me">我</em>':''}</td><td>${escape(r.version)}<small>${escape(r.updated||'')}</small></td><td>${r.draft?`<button class="link" data-sa-edit="${escape(r.id)}">编辑</button> <button class="link" data-sa-test="${escape(r.id)}">测试</button> <button class="link" data-sa-publish="${escape(r.id)}">发布</button>`:r.creator===ME?`<button class="link" data-sa-promote="${escape(r.id)}">发布为科研资产</button>`:''}${r.execution?` <button class="link" data-sa-open="${escape(r.execution)}">来源</button>`:r.task?` <button class="link" data-sa-task="${escape(r.task)}" data-sa-session="${escape(r.session||'')}">来源</button>`:''}</td></tr>`).join('');return walk(root,0)||'<tr><td colspan="7">暂无匹配文件</td></tr>';}
